      right: 0,
      top: 0,
      zIndex: 50, // Higher than most content
    },
    header: {
      padding: '16px 24px',
      borderBottom: '1px solid #e2e8f0', // Equivalent to border-b-gray-200
      display: 'flex',
      justifyContent: 'space-between',
