      border: 'none',
      cursor: 'pointer',
      fontSize: '0.875rem', // text-sm
      color: '#e53e3e', // text-red-600
      marginLeft: '16px',
      '&:hover': {
        textDecoration: 'underline',
      },
      display: 'flex',
      alignItems: 'center',
      padding: '4px 8px',
      borderRadius: '4px',
      transition: 'background-color 0.2s',
    },
    footer: {
      padding: '24px',
      borderTop: '1px solid #e2e8f0', // border-t-gray-200
